import unittest,re
from tools.kjv_archive import load_register,read
class NahumObservingSelfTests(unittest.TestCase):
 def test_divine_threat_and_observing_self(self):
  prior,_=load_register('0.10-kjv.179');lang,manifest=load_register('0.10-kjv.180')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('nahum-'):c for c in read(lang.folder/'nahum-divine-threat-and-observing-self-cases.json')};self.assertEqual(len(cases),47)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship','care'}&set(r['keys']))
  anchors={'1:1': ['kjv_burden_oracle', 'kjv_nahum_prophet kjv_elkoshite'], '1:2': ['kjv_lord revenge:pr kjv_lord revenge:pr', 'wrath for his/enemy:pl keep'], '1:3': ['acquit:neg:fu', 'kjv_whirlwind', 'cloud:pl dust of his/foot:pl'], '1:4': ['all river:pl', 'kjv_bashan', 'kjv_carmel', 'flower of kjv_lebanon'], '1:5': ['hill:pl melt', 'earth at his/presence burn:psv:pr', 'yes world'], '1:6': ['who before his/indignation', 'who in fierce:ev', 'out pour:psv', 'rock:pl'], '1:7': ['kjv_stronghold', 'they that in he trust'], '1:8': ['overflow:cv flood', 'place of it', 'darkness his/enemy:pl pursue'], '1:9': ['what you against kjv_lord', 'two:ord time up rise:neg'], '1:10': ['thorn:pl together entangle', 'kjv_drunkard:pl', 'kjv_stubble entirely dry'], '1:11': ['person out of thou', 'wicked counsellor'], '1:12': ['they quiet', 'likewise many', 'when he through pass', 'ipl thou:a kjv_afflict:perf', 'no more kjv_afflict'], '1:13': ['his/yoke from off thou', 'thy/kjv_binding_restraint:pl'], '1:14': ['thy/name kjv_sow:psv:opt', 'thy/god:pl', 'kjv_graven image', 'melt:psv:adj image', 'ipl thy/grave'], '1:15': ['peace publish:pr be:excl', 'thy/solemn feast:pl', 'thy/vow:pl', 'he entirely off cut'], '2:1': ['fortify:ev keep:imp', 'thy/kjv_loins', 'mighty:adv fortify'], '2:2': ['kjv_excellence of kjv_jacob away turn:perf', 'empty:caus:ag:pl', 'their/kjv_vine branch:pl'], '2:3': ['red make:psv', 'kjv_scarlet', 'flame:cv torch:pl', 'kjv_fir kjv_tree:pl terrible:adv shake'], '2:4': ['each against another', 'broad way:pl', 'torch:pl', 'lightning:pl'], '2:5': ['his/worthy person:pl recount', 'their/walk:ev kjv_stumble', 'defence prepare:psv'], '2:6': ['gate:pl of river:pl', 'palace dissolve:psv'], '2:7': ['kjv_huzzab', 'she up bring', 'her/maid:pl', 'voice of dove:pl', 'their/breast:pl drum'], '2:8': ['kjv_pool of water', 'stand:imp stand:imp', 'none back look'], '2:9': ['spoil of silver', 'spoil of gold', 'pleasing kjv_goods'], '2:10': ['she empty and void', 'knee:pl together strike', 'all kjv_loins', 'black:ev gather'], '2:11': ['young lion:pl', 'old lion', 'kjv_whelp', 'none they:a afraid'], '2:12': ['rend:pa', 'his/female lion:pl choke', 'seize:psv:adj prey'], '2:13': ['ipl against thou', 'her/chariot:pl', 'thy/young lion:pl', 'thy/messenger:pl no more hear'], '3:1': ['woe to bloody city be:excl', 'false word:pl and rob:ev', 'prey depart:neg'], '3:2': ['noise of whip', 'kjv_rattle:ev of wheel:pl', 'kjv_prance:cv horse:pl', 'jump:cv chariot:pl'], '3:3': ['both bright sword', 'glitter:cv kjv_spear', 'no end of their/kjv_corpse:pl', 'their/kjv_corpse:pl kjv_stumble'], '3:4': ['beautiful kjv_harlot', 'mistress of kjv_witchcraft:pl', 'nation:pl', 'kjv_family:pl'], '3:5': ['ipl against thou', 'thy/kjv_skirt_garment:pl upon thy/face', 'thy/bare:ev', 'kingdom:pl thy/shame'], '3:6': ['kjv_abomination:adj kjv_filth', 'vile make', 'gaze:psv:adj thing'], '3:7': ['kjv_nineveh kjv_desolate', 'who she:a mourn', 'where i comfort:ag:pl'], '3:8': ['people:adj kjv_no_egypt', 'among river:pl', 'kjv_rampart sea', 'her/wall from sea'], '3:9': ['kjv_ethiopia and egypt', 'her/strength', 'infinite', 'kjv_put_people and kjv_lubim thy/help:ag:pl'], '3:10': ['her/young child:pl', 'all street:pl in piece:pl', 'kjv_lot:pl', 'chain:pl bind'], '3:11': ['drunk be:fu', 'hide:psv:fu', 'strength because of enemy'], '3:12': ['one_num:ord ripe fig:pl', 'if they shake:psv', 'mouth of eat:ag'], '3:13': ['thy/people in middle of thou woman:pl', 'wide open', 'fire thy/bar:pl'], '3:14': ['water:pl for siege', 'kjv_mortar tread', 'kjv_brickkiln strong'], '3:15': ['kjv_cankerworm', 'thyself many as kjv_cankerworm make:imp', 'thyself many as kjv_locust:pl'], '3:16': ['kjv_merchant:pl above star:pl', 'kjv_cankerworm spoil:pr', 'away flee'], '3:17': ['thy/crown:psv:adj', 'kjv_grasshopper:pl', 'cold day', 'sun rise', 'place where they be:pr know:psv:neg'], '3:18': ['shepherd:pl slumber', 'king of kjv_assyria', 'noble:pl in dust', 'no man they:a gather'], '3:19': ['thy/kjv_bruise:ev', 'thy/wound kjv_grievous', 'report of thou', 'hand:pl over thou together strike', 'always pass:neg:perf?']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('kjv_fir kjv_tree:pl',cases['2-3']['analysis'])
  self.assertIn('kjv_huzzab',cases['2-7']['analysis'])
  self.assertIn('thy/kjv_skirt_garment:pl upon thy/face',cases['3-5']['analysis'])
  self.assertIn('where i comfort:ag:pl',cases['3-7']['analysis'])
  self.assertFalse(any(':du' in c['analysis'] or 'wesg' in c['analysis'] for c in cases.values()))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),4)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
